    explanations: {
      'KO': '상대방이 늦는다고 미안해할 때 한국인들이 가장 많이 쓰는 따뜻한 배려 표현은 \'서두르지 말고 조심해서 천천히 오세요\'예요!',
      'EN': 'When someone apologizes for running late, Koreans warmly comfort them by saying \'서두르지 말고 조심해서 천천히 오세요\' (Don\'t rush, take your time and come safely).',
      'VI': 'Khi đối phương xin lỗi vì đến muộn, câu an ủi ấm áp người Hàn hay dùng nhất là \'서두르지 말고 조심해서 천천히 오세요\' (Đừng vội, cứ đi cẩn thận từ từ nhé).',
      'ZH': '当对方因为迟到而道歉时，韩国人最常说的体贴话是\'서두르지 말고 조심해서 천천히 오세요\'（别着急，注意安全慢慢来）。',
      'JA': '相手が遅れると申し訳なさそうにしている時、韓国人が一番よく使う気遣いフレーズは「서두르지 말고 조심해서 천천히 오세요（急がず気をつけておいで）」です。',
      'ES': 'Cuando alguien se disculpa por llegar tarde, la frase más cordial en coreano es \'서두르지 말고 조심해서 천천히 오세요\' (No te apures, ven con cuidado y con calma).',
      'PT': 'Quando alguém se desculpa pelo atraso, a expressão mais acolhedora é \'서두르지 말고 조심해서 천천히 오세요\' (Não tenha pressa, venha com calma e cuidado).',
