    situations: {
      'KO': '한국 음식이 맵지 않은지 묻는 상대방에게 충분히 견딜 만하고 맛있게 먹을 수 있다고 답하는 상황입니다.',
      'EN': 'A situation where someone asks if the food is too spicy, and you reply that it is manageable and tasty.',
      'VI': 'Tình huống đối phương hỏi món ăn có cay quá không và bạn trả lời rằng hơi cay nhưng vẫn ăn được ngon lành.',
      'ZH': '对方问韩国料理辣不辣，你回答虽然有点辣但味道不错、完全可以接受的情况。',
      'JA': '料理が辛すぎないか尋ねる相手に、少し辛いけれど十分美味しく食べられると答える場面です。',
      'ES': 'Una situación en la que te preguntan si la comida es muy picante y respondes que, aunque pica un poco, se puede comer bien.',
      'PT': 'Uma situação em que perguntam se a comida está apimentada demais e você responde que dá para comer perfeitamente.',
    },
    questions: {
      'KO': '가: 떡볶이가 외국인에게 너무 맵지 않아요?\n나: 조금 맵지만 맛있어서 (   ).',
    },
    options: ['먹을 만해요', '먹을 뻔했어요', '먹을 리가 없어요', '먹지 말아야 해요'],
    answerIndex: 0,
    explanations: {
      'KO': '동사 뒤에 \'-(으)ㄹ 만하다\'를 붙이면 \'어떤 것을 할 가치가 있거나 충분히 감당할 수 있다\'는 뜻을 나타내요!',
      'EN': 'Attaching \'-(으)ㄹ 만하다\' to a verb means something is \'worth doing\' or \'tolerable / manageable\'. \'먹을 만해요\' means \'it is quite edible and good\'.',
      'VI': 'Gắn \'-(으)ㄹ 만하다\' sau động từ mang ý nghĩa \'đáng để làm gì đó hoặc có thể chịu được\'. \'먹을 만해요\' nghĩa là \'vẫn ăn được ngon lành\'.',
      'ZH': '在动词后接\'-(으)ㄹ 만하다\'，表示\'值得做某事\'或\'能够承受/还过得去\'。\'먹을 만해요\'意思是\'挺好吃的，完全能吃\'。',
      'JA': '動詞の後に「-(으)ㄹ 만하다」をつけると「〜する価値がある、十分に〜できる」という意味になります。「먹을 만해요」は「美味しく食べられます」の意味です。',
      'ES': 'Añadir \'-(으)ㄹ 만하다\' a un verbo expresa que vale la pena o que es tolerable. \'먹을 만해요\' significa que está bueno y se deja comer bien.',
      'PT': 'Adicionar \'-(으)ㄹ 만하다\' a um verbo expressa que algo vale a pena ou é tolerável. \'먹을 만해요\' significa que dá para comer bem.',
    },
  ),
