    explanations: {
      'KO': '몸의 체온이 정상보다 높이 올라가는 증상을 \'열이 나다\'라고 해요. 원인이나 이유를 나타낼 때는 \'열이 나서\'를 씁니다.',
      'EN': 'When your body temperature rises above normal, it is called \'열이 나다\' (to have a fever). For reasons, use \'열이 나서\'.',
