      'ZH': '体温高于正常状态的发烧症状在韩语中是\'열이 나다\'。表示原因时使用\'열이 나서（因为发烧）\'。',
      'JA': '体温が平熱より高くなる症状を「열이 나다（熱が出る）」と言います。理由を表す時は「열이 나서（熱が出て）」になります。',
